  string ModuleDetail(ModuleSpec m){if(m.Bypass)return L("旁路 · 原声通过","Bypassed · dry signal");switch(m.Kind){case "equalizer":return m.Preset;case "volume":case "limiter":return Math.Round(m.Gain*100)+"%";case "mixer":return m.Mode;case "voice":return m.Mode+" "+m.Semitones;case "rtpin":case "rtpout":return m.Host+":"+m.Port;case "delay":return m.DelayMs+" ms";default:return L("已启用","Enabled");}}
