  void RefreshApplicationBindings(){bool changed=false;var bindings=settings.Items<AppBinding>("AudioAppNodes");foreach(var binding in bindings){var match=AirBridge.Routing.ApplicationIdentity.Resolve(binding.Source,binding.Path,applications);if(match==null)continue;if(binding.Source!=match.Id||binding.Path!=match.Path||binding.Name!=match.Name){binding.Source=match.Id;binding.Path=match.Path;binding.Name=match.Name;changed=true;}}if(changed){settings.Set("AudioAppNodes",bindings);settings.Save();}}
  string AppState(AppBinding app){switch(AirBridge.Routing.ApplicationIdentity.Status(app.Source,app.Path,applications)){case "ready":return L("应用输出 · 双击更换","Application output · double-click to edit");case "ambiguous":return L("多个匹配实例 · 双击选择","Multiple instances · choose one");case "closed":return L("等待应用启动","Waiting for application");default:return L("请选择应用","Select an application");}}
  string ResolveSource(string id){if(!id.StartsWith("app:"))return id;var binding=settings.Items<AppBinding>("AudioAppNodes").FirstOrDefault(a=>a.Id==id);if(binding==null||String.IsNullOrEmpty(binding.Source))throw new InvalidOperationException(L("应用未选择或已退出，请编辑应用节点。","Select a running application in the node editor."));return binding.Source;}
  GraphPlan BuildPlan(){var edges=board.Links.Where(l=>l.Enabled).Select(l=>{if(new[]{l.Source,l.Target}.Any(id=>!id.StartsWith("app:")&&!board.Nodes.Any(n=>n.Id==id&&n.Available)))throw new InvalidOperationException(L("连线设备不可用。","Linked device unavailable."));return new GraphEdge{Source=ResolveSource(l.Source),Target=l.Target,Gain=(float)l.Gain/100};}).ToArray();var modules=SettingsStore.Clone(settings.Items<ModuleSpec>("AudioModules"));foreach(var m in modules)if((m.SelectedSource??"").StartsWith("app:"))m.SelectedSource=ResolveSource(m.SelectedSource);return GraphPlan.Create(edges,modules);}
  sealed class CatalogItem{public string Id,Kind,Name;public int Group;}
  void RenderCatalog(){if(board==null)return;var panel=U<StackPanel>("NodeCatalog");panel.Children.Clear();var items=new List<CatalogItem>{new CatalogItem{Kind="application",Name=L("应用独立音频","Application audio"),Group=1}};items.AddRange(catalog.Where(n=>!n.Id.StartsWith("m:")&&!n.Id.StartsWith("app:")).Select(n=>new CatalogItem{Id=n.Id,Name=n.Name,Group=n.Input?1:2}));items.AddRange(kinds.Select(k=>new CatalogItem{Kind=k,Name=ModuleName(k),Group=k=="rtpin"?1:k=="rtpout"?2:3}));int group=U<ComboBox>("NodeCategory").SelectedIndex;string query=U<TextBox>("NodeSearch").Text.Trim();foreach(var item in items.Where(i=>(group<=0||group==i.Group)&&i.Name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)){var current=item;var button=Button("",()=>AddNode(current));button.HorizontalContentAlignment=HorizontalAlignment.Stretch;button.Padding=new Thickness(10);button.Margin=new Thickness(0,0,0,8);button.MinHeight=60;var text=new StackPanel();var title=Label(item.Name,12);title.TextWrapping=TextWrapping.NoWrap;title.TextTrimming=TextTrimming.CharacterEllipsis;text.Children.Add(title);var subtitle=Label((item.Group==1?L("输入","Input"):item.Group==2?L("输出","Output"):L("处理","Process"))+" · "+(board.Nodes.Any(n=>n.Id==item.Id)?L("已添加","Added"):L("＋ 添加","+ Add")),10,"7C8595");subtitle.Margin=new Thickness(0,4,0,0);text.Children.Add(subtitle);button.Content=text;panel.Children.Add(button);}if(panel.Children.Count==0)panel.Children.Add(Label(L("没有匹配的节点","No matching nodes"),12));}
  void AddNode(CatalogItem item){if(routes.Busy)return;string id=item.Id;if(item.Kind=="application"){id="app:"+Guid.NewGuid().ToString("N");settings.Set("AudioAppNodes",settings.Items<AppBinding>("AudioAppNodes").Concat(new[]{new AppBinding{Id=id,Source="",Name=item.Name}}).ToArray());}else if(!String.IsNullOrEmpty(item.Kind)){id="m:"+Guid.NewGuid().ToString("N");settings.Set("AudioModules",settings.Items<ModuleSpec>("AudioModules").Concat(new[]{new ModuleSpec{Id=id,Kind=item.Kind,Enabled=!new[]{"mute","record","rtpin","rtpout"}.Contains(item.Kind),Mode=item.Kind=="voice"?"pitch":"mix",Path=System.IO.Path.Combine(settings.Root,"Recordings")}}).ToArray());}else if(board.Nodes.Any(n=>n.Id==id)){board.SelectNode(id);return;}settings.Set("AudioCanvasNodes",settings.Items<string>("AudioCanvasNodes").Concat(new[]{id}).Distinct().ToArray());SaveGraph();RefreshGraph();var center=board.ViewCenter();board.MoveNode(id,center.X-122,center.Y-40);board.SelectNode(id);if(item.Kind=="application")EditNode(id);}
  void RemoveNode(string id){if(routes.Busy||String.IsNullOrEmpty(id))return;settings.Set("AudioCanvasNodes",settings.Items<string>("AudioCanvasNodes").Where(x=>x!=id).ToArray());settings.Set("AudioAppNodes",settings.Items<AppBinding>("AudioAppNodes").Where(x=>x.Id!=id).ToArray());settings.Set("AudioModules",settings.Items<ModuleSpec>("AudioModules").Where(x=>x.Id!=id).ToArray());board.Links.RemoveAll(l=>l.Source==id||l.Target==id);board.ForgetPosition(id);SaveGraph();RefreshGraph();}
