  void EditApplication(string id){var binding=settings.Items<AppBinding>("AudioAppNodes").FirstOrDefault(a=>a.Id==id);if(binding==null)return;var dialog=Dialog(L("应用独立音频","Application audio"));var panel=new StackPanel{Margin=new Thickness(20)};dialog.Content=panel;panel.Children.Add(Label(L("先让应用播放声音，再刷新。多输出与效果链需启用 VB-CABLE 扩展。","Play audio, then refresh. Multiple outputs and effects require VB-CABLE."),12));var picker=new ComboBox{Height=36,Margin=new Thickness(0,14,0,0),DisplayMemberPath="Name",ItemsSource=applications,SelectedItem=applications.FirstOrDefault(a=>a.Id==binding.Source)};panel.Children.Add(picker);var refresh=Button(L("刷新应用","Refresh applications"),()=>{});refresh.Click+=async(s,e)=>{refresh.IsEnabled=false;try{var result=await Task.Run(()=>GraphRuntime.Applications());applications=result;RefreshApplicationBindings();picker.ItemsSource=applications;picker.SelectedItem=AirBridge.Routing.ApplicationIdentity.Resolve(binding.Source,binding.Path,applications);}catch(Exception ex){Error(ex);}finally{refresh.IsEnabled=true;}};refresh.HorizontalAlignment=HorizontalAlignment.Right;refresh.MinWidth=110;refresh.Margin=new Thickness(0,8,0,12);panel.Children.Add(refresh);DialogActions(dialog,panel,()=>{var choice=picker.SelectedItem as ApplicationInput;if(choice==null)throw new InvalidOperationException(L("请选择应用","Select an application"));var all=settings.Items<AppBinding>("AudioAppNodes");if(all.Any(a=>a.Id!=id&&a.Source==choice.Id))throw new InvalidOperationException(L("该应用已有输入节点","Application already has a node"));foreach(var a in all)if(a.Id==id){a.Source=choice.Id;a.Name=choice.Name;a.Path=choice.Path;}settings.Set("AudioAppNodes",all);});Motion.Attach(dialog);dialog.ShowDialog();}
