   Action<string,double,double,double> slider=(name,min,max,mult)=>{var f=typeof(ModuleSpec).GetField(name);var stack=new StackPanel{Orientation=Orientation.Horizontal};var value=Label("",12);var control=new Slider{Width=230,Minimum=min,Maximum=max,Value=Convert.ToDouble(f.GetValue(m))*mult};value.Text=Math.Round(control.Value).ToString();control.ValueChanged+=(s,e)=>{f.SetValue(m,(float)(control.Value/mult));value.Text=Math.Round(control.Value).ToString();};stack.Children.Add(control);stack.Children.Add(value);field(name,stack);};
   var textFields=new Dictionary<string,TextBox>();Action<string> text=name=>{var f=typeof(ModuleSpec).GetField(name);var box=new TextBox{Width=300,Text=Convert.ToString(f.GetValue(m)),Padding=new Thickness(10,7,10,7)};textFields[name]=box;box.TextChanged+=(s,e)=>{try{f.SetValue(m,f.FieldType==typeof(int)?(object)Int32.Parse(box.Text):box.Text);}catch{box.ToolTip=L("请输入整数","Enter an integer");}};field(name,box);};
   switch(m.Kind){case "equalizer":combo("Preset",new[]{"flat","bass","voice","treble","warm"},new[]{L("原声","Flat"),L("低音增强","Bass"),L("人声清晰","Voice"),L("高音明亮","Treble"),L("温暖","Warm")});break;case "volume":slider("Gain",0,100,100);break;case "limiter":slider("Gain",5,100,100);break;case "mixer":combo("Mode",new[]{"mix","select"},new[]{L("全部混合（平均增益）","Mix all (averaged gain)"),L("选择一路","Select one")});var links=board.Links.Where(l=>l.Target==m.Id).ToArray();combo("SelectedSource",new[]{""}.Concat(links.Select(l=>l.Source)).ToArray(),new[]{L("第一路","First input")}.Concat(links.Select(l=>l.SourceName)).ToArray());break;case "voice":combo("Mode",new[]{"pitch","robot"},new[]{L("音高变化","Pitch shift"),L("机器人","Robot")});slider("Semitones",-12,12,1);break;case "delay":slider("DelayMs",0,1000,1);slider("Feedback",0,80,100);break;case "record":text("Path");panel.Children.Add(Label("WAV · 44.1 kHz / stereo / PCM16",12));break;case "rtpin":case "rtpout":text("Host");text("Port");text("PayloadType");panel.Children.Add(Label("RTP L16/44100/2 · "+L("不自动修改防火墙或进行公网穿透","No automatic firewall or NAT changes"),12));break;}
   if(effectNode){panel.Children.Add(Button(L("应用此效果参数","Apply effect parameters"),()=>{if(routes.Busy)return;m.Enabled=enabled.IsChecked==true;m.Bypass=bypass.IsChecked==true;if(!routes.Engine.TryUpdateEffect(m))throw new InvalidOperationException(L("请先应用包含此效果的连线。","Apply a route containing this effect first."));settings.Set("AudioModules",settings.Items<ModuleSpec>("AudioModules").Select(x=>x.Id==m.Id?m.Copy():x).ToArray());var running=settings.Get<RunningGraph>("LastRunningGraph");if(running!=null){running.Modules=(running.Modules??new ModuleSpec[0]).Select(x=>x.Id==m.Id?m.Copy():x).ToArray();settings.Set("LastRunningGraph",running);}settings.Save();graphSignature="";RefreshGraph();Notify(L("效果参数已应用，音频连接保持不变。","Effect applied without reopening audio."));}));}
   panel.Children.Add(Label(L(effectNode?"应用参数立即生效；保存仅更新草稿。取消不会撤销已应用参数。":"保存为待应用配置；取消不改变当前声音。",effectNode?"Apply changes sound immediately; Save updates the draft. Cancel does not undo applied parameters.":"Save to draft; cancel leaves current audio unchanged."),12));DialogActions(dialog,panel,()=>{foreach(var entry in textFields){var f=typeof(ModuleSpec).GetField(entry.Key);int number;if(f.FieldType==typeof(int)){if(!Int32.TryParse(entry.Value.Text,out number))throw new ArgumentException(entry.Key+L(" 请输入整数"," requires an integer"));f.SetValue(m,number);}else f.SetValue(m,entry.Value.Text);}m.Enabled=enabled.IsChecked==true;if(effectNode)m.Bypass=bypass.IsChecked==true;GraphCompiler.ValidateModule(m);settings.Set("AudioModules",settings.Items<ModuleSpec>("AudioModules").Select(x=>x.Id==m.Id?m:x).ToArray());});Motion.Attach(dialog);dialog.ShowDialog();}
 }
}
